-- Seed 9 Sprin historis nyata + 180 kelompok + 1.525 baris penugasan, dari
-- siandi_seed_v1.json (sprin[] dan penugasan[]). Personel dicocokkan ke roster
-- pengguna aktif (NRP dinormalisasi -- sebagian data lama kehilangan angka nol di
-- depan, mis. "2040502" vs NRP asli "02040502"); yang tidak cocok (23 orang -- 18
-- dengan NRP yang sudah tidak aktif, 5 tanpa NRP tercatat sama sekali di sumber)
-- masuk personel_non_kuatpers, sesuai pola PRD (~97% match rate terhadap KUATPERS).
--
-- PENTING: migration ini TIDAK idempoten seperti yang lain -- personel_non_kuatpers
-- tidak punya unique constraint alami. Jangan dijalankan dua kali.
--
-- Trigger trg_surat_perintah_before_write dimatikan sementara: trigger itu sengaja
-- menolak INSERT langsung berstatus TERBIT (RLS-06, untuk alur normal aplikasi),
-- tapi ke-9 Sprin ini memang sudah terbit sejak sebelum sistem ada -- diimpor
-- langsung sebagai riwayat, bukan lewat alur ajukan/setujui.

alter table public.surat_perintah disable trigger trg_surat_perintah_before_write;

insert into public.surat_perintah (
  nomor_agenda, nomor_lengkap, jenis_kegiatan_id, perihal, tanggal_mulai, tanggal_selesai,
  jam_apel, status, disusun_oleh, disetujui_oleh, disetujui_pada
)
select
  x.nomor_agenda, x.nomor_lengkap, jk.id, x.perihal, x.tanggal_mulai::date, x.tanggal_selesai::date,
  nullif(x.jam_apel, '')::time, 'TERBIT'::status_surat_perintah,
  (select id from public.pengguna where nrp = '87121335'),
  (select id from public.pengguna where nrp = '76010326'),
  x.tanggal_mulai::date::timestamptz
from jsonb_to_recordset('[{"kode": "PEKAT-2026", "nomor_agenda": 368, "nomor_lengkap": "SPRIN/368/II/OPS.1.3./2026", "jenis_kegiatan_nama": "OPERASI KEPOLISIAN KEWILAYAHAN", "perihal": "Operasi Kepolisian Pekat I Lodaya 2026", "tanggal_mulai": "2026-02-21", "tanggal_selesai": "2026-03-02", "jam_apel": null, "penandatangan": "KAPOLRES"}, {"kode": "KETUPAT-2026", "nomor_agenda": 535, "nomor_lengkap": "SPRIN/535/III/OPS.1.2.3./2026", "jenis_kegiatan_nama": "OPERASI KEPOLISIAN HARI BESAR", "perihal": "Pengamanan Hari Raya Idul Fitri 1447 H", "tanggal_mulai": "2026-03-13", "tanggal_selesai": "2026-03-25", "jam_apel": null, "penandatangan": "KAPOLRES"}, {"kode": "PAM-WAKAPOLRI-20JUN", "nomor_agenda": 1421, "nomor_lengkap": "SPRIN/1421/VI/PAM.2.2./2026", "jenis_kegiatan_nama": "PENGAMANAN VIP/VVIP", "perihal": "Pengamanan Kedatangan Wakapolri ke Wilkum Polres Cimahi", "tanggal_mulai": "2026-06-20", "tanggal_selesai": "2026-06-20", "jam_apel": "15:00", "penandatangan": "KAPOLRES"}, {"kode": "PAM-KUNKER-KAPOLRI", "nomor_agenda": 1491, "nomor_lengkap": "SPRIN/1491/VII/PAM.2.2./2026", "jenis_kegiatan_nama": "PENGAMANAN VIP/VVIP", "perihal": "Pengamanan Kunjungan Kerja Kapolri ke Sespim Lemdiklat Polri", "tanggal_mulai": "2026-07-02", "tanggal_selesai": "2026-07-03", "jam_apel": "09:00", "penandatangan": "KAPOLRES"}, {"kode": "PAM-UNRAS-SPSB-CMI", "nomor_agenda": 1600, "nomor_lengkap": "SPRIN/1600/VII/PAM.3.2./2026", "jenis_kegiatan_nama": "PENGAMANAN UNJUK RASA", "perihal": "Pengamanan Aksi Unjuk Rasa Aliansi SP/SB Kota Cimahi", "tanggal_mulai": "2026-07-23", "tanggal_selesai": "2026-07-23", "jam_apel": "09:00", "penandatangan": "KAPOLRES"}, {"kode": "KRYD-25JUL", "nomor_agenda": 1605, "nomor_lengkap": "SPRIN/1605/VII/PAM.1.3.2./2026", "jenis_kegiatan_nama": "KEGIATAN RUTIN YANG DITINGKATKAN", "perihal": "Kegiatan Rutin yang Ditingkatkan / Patroli dan Razia Skala Besar", "tanggal_mulai": "2026-07-25", "tanggal_selesai": "2026-07-25", "jam_apel": "21:00", "penandatangan": "KAPOLRES"}, {"kode": "KRYD-26JUL", "nomor_agenda": 1686, "nomor_lengkap": "SPRIN/1686/VII/PAM.1.3.2./2026", "jenis_kegiatan_nama": "KEGIATAN RUTIN YANG DITINGKATKAN", "perihal": "Kegiatan Rutin yang Ditingkatkan / Patroli dan Razia Skala Besar", "tanggal_mulai": "2026-07-26", "tanggal_selesai": "2026-07-26", "jam_apel": "21:00", "penandatangan": "KAPOLRES"}, {"kode": "PAM-UNRAS-KEMENDAGRI", "nomor_agenda": 1694, "nomor_lengkap": "SPRIN/1694/VII/PAM.3.2./2026", "jenis_kegiatan_nama": "PENGAMANAN UNJUK RASA", "perihal": "Pengamanan Keberangkatan Massa KC FSPMI dan DPC SPN ke Kemendagri Jakarta", "tanggal_mulai": "2026-07-28", "tanggal_selesai": "2026-07-28", "jam_apel": "05:30", "penandatangan": "KAPOLRES"}, {"kode": "PAM-UNRAS-KOALISI7", "nomor_agenda": 1702, "nomor_lengkap": "SPRIN/1702/VII/PAM.3.2./2026", "jenis_kegiatan_nama": "PENGAMANAN UNJUK RASA", "perihal": "Pengamanan Aksi Unjuk Rasa Koalisi 7 SP-SB Kab. Bandung Barat", "tanggal_mulai": "2026-07-30", "tanggal_selesai": "2026-07-30", "jam_apel": "08:00", "penandatangan": "WAKAPOLRES (a.n. Kapolres)"}]'::jsonb) as x(
  kode text, nomor_agenda int, nomor_lengkap text, jenis_kegiatan_nama text, perihal text,
  tanggal_mulai text, tanggal_selesai text, jam_apel text, penandatangan text
)
join public.jenis_kegiatan jk on jk.nama = x.jenis_kegiatan_nama
where not exists (select 1 from public.surat_perintah sp where sp.nomor_lengkap = x.nomor_lengkap);

alter table public.surat_perintah enable trigger trg_surat_perintah_before_write;

